            inputOutputExample: 'import { renderHook, act } from \'@testing-library/react\';\nimport { useCounter } from \'./useCounter\';\n\ntest(\'clamps at max\', () => {\n  const { result } = renderHook(() => useCounter(0, { max: 3 }));\n  act(() => { result.current.increment(); result.current.increment(); result.current.increment(); result.current.increment(); });\n  expect(result.current.count).toBe(3); // not 4\n});\n\ntest(\'reset returns to initial value\', () => {\n  const { result } = renderHook(() => useCounter(5));\n  act(() => { result.current.increment(); result.current.reset(); });\n  expect(result.current.count).toBe(5);\n});',
            hint: 'renderHook renders the hook in isolation. act() wraps state updates so React can process them. Test what the hook DOES (its behavior from the caller\'s perspective) — not what useState calls it makes internally.',
