export function getWeekByNum(num: number): Week | undefined {
  return curriculum.find(w => w.num === num);
}

export function getAllTaskIds(): string[] {
  const ids: string[] = [];
  for (const week of curriculum) {
    for (const day of week.days) {
      ids.push(`${day.id}_t0`);
      ids.push(`${day.id}_t1`);
      ids.push(`${day.id}_t2`);
    }
    ids.push(`${week.sunday.id}_mock`);
    ids.push(`${week.sunday.id}_proj`);
    week.sunday.miniProject.coreFeatures.forEach((_, i) => {
      ids.push(`${week.sunday.id}_feat_${i}`);
    });
  }
  return ids;
}

export function getTotalTaskCount(): number {
  return getAllTaskIds().length;
}
